"""sklearn.utils.sparsefuncs — sparse-matrix helpers.

The shim treats every input as dense (since we don't bundle scipy
sparse), so these largely fall through to dense numpy ops."""

import numpy as _np


def _to_dense(X):
    return X.toarray() if hasattr(X, 'toarray') else _np.asarray(X)


def mean_variance_axis(X, axis=0, weights=None, return_sum_weights=False):
    """Compute column- or row-wise mean and variance."""
    X = _to_dense(X)
    if weights is None:
        m, v = X.mean(axis=axis), X.var(axis=axis)
        n = X.shape[axis]
    else:
        weights = _np.asarray(weights)
        m = _np.average(X, axis=axis, weights=weights)
        v = _np.average((X - _np.expand_dims(m, axis)) ** 2, axis=axis, weights=weights)
        n = weights.sum()
    return (m, v, n) if return_sum_weights else (m, v)


def incr_mean_variance_axis(X, axis=0, last_mean=0, last_var=0, last_n=0,
                              weights=None):
    """Online mean/variance update."""
    new_m, new_v, new_n = mean_variance_axis(X, axis, weights, return_sum_weights=True)
    total_n = last_n + new_n
    if total_n == 0: return new_m, new_v, total_n
    upd_m = (last_n * last_mean + new_n * new_m) / total_n
    delta = new_m - last_mean
    upd_v = (last_n * last_var + new_n * new_v +
              last_n * new_n * delta ** 2 / total_n) / total_n
    return upd_m, upd_v, total_n


def inplace_column_scale(X, scale):
    """Scale each column of X in place."""
    X = _to_dense(X)
    X *= scale
    return X


def inplace_row_scale(X, scale):
    """Scale each row of X in place."""
    X = _to_dense(X)
    X *= scale[:, None]
    return X


def inplace_swap_row(X, m, n):
    X = _to_dense(X)
    X[[m, n]] = X[[n, m]]
    return X


def inplace_swap_column(X, m, n):
    X = _to_dense(X)
    X[:, [m, n]] = X[:, [n, m]]
    return X


def count_nonzero(X, axis=None, sample_weight=None):
    X = _to_dense(X)
    if sample_weight is not None:
        return (X * sample_weight[:, None] != 0).sum(axis=axis)
    return _np.count_nonzero(X, axis=axis)


def csc_median_axis_0(X):
    X = _to_dense(X)
    return _np.median(X, axis=0)


def min_max_axis(X, axis=0, ignore_nan=False):
    X = _to_dense(X)
    func_min = _np.nanmin if ignore_nan else _np.min
    func_max = _np.nanmax if ignore_nan else _np.max
    return func_min(X, axis=axis), func_max(X, axis=axis)


def inplace_csr_column_scale(X, scale):    return inplace_column_scale(X, scale)
def inplace_csr_row_normalize_l1(X):
    X = _to_dense(X); norm = _np.abs(X).sum(axis=1, keepdims=True); norm[norm == 0] = 1
    X /= norm; return X
def inplace_csr_row_normalize_l2(X):
    X = _to_dense(X); norm = _np.linalg.norm(X, axis=1, keepdims=True); norm[norm == 0] = 1
    X /= norm; return X


